interface Renderer { void circle(double r); }                  // Implementor
abstract class Shape {                                         // Abstraction
    protected final Renderer renderer;
    protected Shape(Renderer renderer) { this.renderer = renderer; }
    public abstract void draw();
}
final class Circle extends Shape {                             // RefinedAbstraction
    private final double radius;
    Circle(Renderer r, double radius) { super(r); this.radius = radius; }
    public void draw() { renderer.circle(radius); }
}

sealed interface Renderer permits Software, Cairo { void circle(double r); }
record Software(double dpi) implements Renderer {
    public void circle(double r) { /* software raster */ }
}
record Cairo(String surface) implements Renderer {
    public void circle(double r) { /* cairo_arc */ }
}

static void draw(Renderer r, double radius) {
    switch (r) {                        // exhaustive: no default needed
        case Software s -> s.circle(radius);
        case Cairo c    -> c.circle(radius);
    }
}

